package vpiso;

import java.io.ByteArrayInputStream;
import java.io.DataInputStream;
import java.io.IOException;
import java.util.Base64;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.zip.InflaterInputStream;

/** Offline masks of low-alpha, planar ground-shadow components in the shipped native artwork.
 * Stores coordinates only, never the original game's color artwork. Generated from build019-fixed and build029-fixed reviewed evidence. */
public final class NativeShadowMasks {
    public record Mask(int width,int height,byte[] bits) {}
    private static final Map<String,Mask> MASKS=load();
    public static Mask get(String name) { return MASKS.get(name); }
    public static Set<String> names() { return MASKS.keySet(); }
    public static int size() { return MASKS.size(); }
    private static Map<String,Mask> load() {
        String packed=String.join("",new String[]{
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            "",
            ""
        });
        try (DataInputStream input=new DataInputStream(new InflaterInputStream(
                new ByteArrayInputStream(Base64.getDecoder().decode(packed))))) {
            Map<String,Mask> masks=new HashMap<>();
            for(int i=0;i<1111;i++) {
                String name=input.readUTF();
                int width=input.readUnsignedShort(),height=input.readUnsignedShort(),size=input.readInt();
                byte[] bits=input.readNBytes(size);
                if(size!=(width*height+7)/8 || bits.length!=size) throw new IOException("Bad native shadow mask size");
                masks.put(name,new Mask(width,height,bits));
            }
            if(input.read()!=-1) throw new IOException("Trailing native shadow mask data");
            return Map.copyOf(masks);
        } catch(IOException error) { throw new ExceptionInInitializerError(error); }
    }
    private NativeShadowMasks() {}
}
